export default function Home() {
  return (
    <div>
      <header>
        <h1>Buddy Budget</h1>
        <nav>
          <a href="#">Home</a>
          <a href="#features">Features</a>
          <a href="#">Login</a>
        </nav>
      </header>

      <section className="hero">
        <h2>Take Control of Your Money</h2>
        <p>Simple budgeting for students and young adults. Track spending, set goals, and build better financial habits.</p>
        <div className="buttons">
          <button className="btn btn-primary" onClick={() => alert('Sign up coming soon!')}>Get Started</button>
          <button className="btn btn-secondary" onClick={testBackend}>Test Backend</button>
        </div>
      </section>

      <section className="features" id="features">
        <div className="feature">
          <h3>💰 Track Expenses</h3>
          <p>Log your daily spending and see exactly where your money goes.</p>
        </div>
        <div className="feature">
          <h3>📊 Budget Insights</h3>
          <p>Visualize your finances and stay on top of your monthly goals.</p>
        </div>
        <div className="feature">
          <h3>🎯 Savings Goals</h3>
          <p>Set savings targets and monitor your progress over time.</p>
        </div>
      </section>

      <footer>
        <p>© 2026 Buddy Budget. All rights reserved.</p>
      </footer>
    </div>
  );
}

async function testBackend() {
  try {
    const res = await fetch('/api/test');
    const data = await res.json();
    alert(data.message);
  } catch (err) {
    alert('Backend not reachable');
  }
}